sys_script.script:
// SN Release Impact Digest — Business Rule: Auto-generate run_id on insert
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function executeRule(current, previous /*null when async*/) {

    if (!current.run_id) {
        current.run_id = gs.generateGUID();
    }

    if (!current.started_at) {
        current.started_at = new GlideDateTime().getDisplayValue();
    }

    if (!current.status) {
        current.status = 'pending';
    }

})(current, previous);
